{
  "service": "user-service",
  "action": "get_user",
  "componentType": "rest",
  "description": "Fetch user by ID from upstream API",
  "config": {
    "request": {
      "uri": "https://jsonplaceholder.typicode.com/users/$.context.id",
      "method": "GET"
    },
    "response": {
      "transformation": {
        "getUserResponse": {
          "userId": "$.response.id",
          "userName": "$.response.name",
          "userEmail": "$.response.email"
        }
      }
    }
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Create order in upstream system with auth, retry, and response mapping",
  "config": {
    "request": {
      "uri": "https://api.example.com/orders",
      "method": "POST",
      "contentType": "application/json",
      "headers": {
        "X-Tenant-Id": "$.context.tenantId",
        "X-Request-Id": "$.context.requestId"
      },
      "auth": {
        "oauth2": {
          "clientId": "$env.ORDER_API_CLIENT_ID",
          "clientSecret": "$env.ORDER_API_CLIENT_SECRET",
          "accessTokenUri": "https://auth.example.com/oauth/token",
          "scope": "orders:write"
        }
      },
      "payloadTemplate": {
        "customerId": "$.context.customerId",
        "items": "$.context.items",
        "totalAmount": "$.context.totalAmount"
      }
    },
    "timeout": {
      "connect": 5000,
      "response": 30000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504]
    },
    "response": {
      "validation": {
        "rules": [
          { "expression": "$.response.id != null", "message": "Order ID is missing" },
          { "expression": "$.response.status == 'created'", "message": "Order not created" }
        ]
      },
      "transformation": {
        "createOrderResponse": {
          "orderId": "$.response.id",
          "status": "$.response.status",
          "createdAt": "$.response.created_at"
        }
      }
    }
  },
  "condition": "$.context.customerId != null",
  "metaData": {
    "owner": "platform-team",
    "slack": "#orders-alerts"
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Updated: increased timeout and added circuit breaker",
  "config": {
    "request": {
      "uri": "https://api.example.com/orders",
      "method": "POST",
      "contentType": "application/json",
      "auth": {
        "oauth2": {
          "clientId": "$env.ORDER_API_CLIENT_ID",
          "clientSecret": "$env.ORDER_API_CLIENT_SECRET",
          "accessTokenUri": "https://auth.example.com/oauth/token",
          "scope": "orders:write"
        }
      },
      "payloadTemplate": {
        "customerId": "$.context.customerId",
        "items": "$.context.items",
        "totalAmount": "$.context.totalAmount"
      }
    },
    "timeout": {
      "connect": 5000,
      "response": 60000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504],
      "circuitBreaker": {
        "failureThreshold": 5,
        "windowSize": 60000,
        "openDuration": 30000,
        "halfOpenMaxAttempts": 3
      }
    },
    "response": {
      "validation": {
        "rules": [
          { "expression": "$.response.id != null", "message": "Order ID is missing" },
          { "expression": "$.response.status == 'created'", "message": "Order not created" }
        ]
      },
      "transformation": {
        "createOrderResponse": {
          "orderId": "$.response.id",
          "status": "$.response.status",
          "createdAt": "$.response.created_at"
        }
      }
    }
  }
}

{
  "service": "data-mapper",
  "action": "enrich_order",
  "componentType": "mapper",
  "description": "Enrich order data with computed fields",
  "config": {
    "template": {
      "orderId": "$.context.orderId",
      "totalWithTax": "$.context.subtotal * 1.1",
      "itemCount": "$.context.items.length"
    },
    "condition": "$.context.orderId != null",
    "response": {
      "transformation": {
        "enrichOrderResponse": {
          "orderId": "$.context.output.enrichOrderResponse.orderId",
          "totalWithTax": "$.context.output.enrichOrderResponse.totalWithTax"
        }
      }
    }
  }
}

{
  "service": "customer-db",
  "action": "get_customer",
  "componentType": "database",
  "description": "Fetch customer by ID",
  "config": {
    "operation": "SELECT",
    "query": "SELECT * FROM customers WHERE id = $id",
    "parameters": {
      "id": "$.context.customerId"
    },
    "response": {
      "transformation": {
        "getCustomerResponse": {
          "customer": "$.response.rows[0]"
        }
      }
    }
  }
}

{
  "service": "order-db",
  "action": "save_order",
  "componentType": "database",
  "description": "Save order to database",
  "config": {
    "operation": "INSERT",
    "query": "INSERT INTO orders (customer_id, total, status) VALUES ($customerId, $total, $status) RETURNING *",
    "parameters": {
      "customerId": "$.context.customerId",
      "total": "$.context.total",
      "status": "$.context.status"
    },
    "response": {
      "validation": {
        "rules": [
          { "expression": "$.response.rows != null", "message": "Order not saved" }
        ]
      },
      "transformation": {
        "saveOrderResponse": {
          "orderId": "$.response.rows[0].id",
          "createdAt": "$.response.rows[0].created_at"
        }
      }
    }
  }
}

{
  "service": "calc-service",
  "action": "calculate_total",
  "componentType": "script",
  "description": "Calculate order total with tax",
  "config": {
    "expression": "(function($context){ return { total: $context.subtotal * 1.1 }; })()",
    "response": {
      "transformation": {
        "calculateTotalResponse": {
          "total": "$.response.total"
        }
      }
    }
  }
}

{
  "service": "calc-service",
  "action": "calculate_discount",
  "componentType": "script",
  "description": "Calculate discount based on customer tier",
  "config": {
    "expression": "(function($context){ const discount = $context.tier === 'gold' ? 0.2 : 0.1; return { discount: $context.subtotal * discount, tier: $context.tier }; })()",
    "condition": "$.context.subtotal != null && $.context.tier != null",
    "response": {
      "validation": {
        "rules": [
          { "expression": "$.response.discount >= 0", "message": "Invalid discount calculated" }
        ]
      },
      "transformation": {
        "calculateDiscountResponse": {
          "discount": "$.response.discount",
          "tier": "$.response.tier"
        }
      }
    }
  }
}

{
  "service": "order-queue",
  "action": "enqueue_order",
  "componentType": "sqs",
  "description": "Push order to FIFO queue",
  "config": {
    "queueName": "order-queue.fifo",
    "isFifo": true,
    "groupId": "$.context.orderGroupId",
    "messageBody": {
      "orderId": "$.context.orderId",
      "customerId": "$.context.customerId",
      "total": "$.context.total"
    },
    "condition": "$.context.orderId != null",
    "response": {
      "transformation": {
        "enqueueOrderResponse": {
          "messageId": "$.response.messageId",
          "sequenceNumber": "$.response.sequenceNumber"
        }
      }
    }
  }
}
